def use_system_certs(force=False):
    "Verify TLS against the OS trust store rather than `certifi`. False if `truststore` is missing, or off by `RISHI_SYSTEM_CERTS=0`."
    if not force and os.getenv('RISHI_SYSTEM_CERTS', '1') == '0': return False
    try: import truststore
    except ImportError: return False
    truststore.inject_into_ssl()    # idempotent: it rebinds `ssl.SSLContext` to its own
    return True

#: Done once, on import. A proxy that intercepts TLS breaks every hosted backend at once, and the
#: caller who would know to ask for this has no way to know before the first failure.
system_certs = use_system_certs()

