class ToolCall(dict):
    "One tool call in canonical form. A `dict` subclass, so anything that indexes it keeps working."
    def __init__(self, name='', arguments=None, id=None, server=False):
        super().__init__(id=id or f'call_{uuid.uuid4().hex[:8]}', type='function',
                         function={'name': name, 'arguments': arguments if arguments is not None else {}})
        if server: self['server'] = True
    @property
    def name(self): return self['function'].get('name', '')
    @property
    def arguments(self): return self['function'].get('arguments') or {}
    @property
    def server(self):
        "True if the *provider* runs this tool (hosted web search and friends), so we must not."
        return bool(self.get('server'))
    def __repr__(self): return f'ToolCall({self.name}, {self.arguments})'

def tc_name(tc):
    "Name of a tool call, however it was built."
    return (tc.get('function') or {}).get('name', '')

def mk_tool_res_msg(tc, result):
    "Canonical `role='tool'` message carrying `result` back for tool call `tc`."
    return {'role': 'tool', 'tool_call_id': tc.get('id'), 'name': tc_name(tc), 'content': str(result)}

def mk_tool_res_msgs(tcs, results):
    "Canonical tool-result messages for several calls at once."
    return [mk_tool_res_msg(tc, r) for tc, r in zip(tcs, results)]

# %% ../nbs/00_core.ipynb #11c2627de6f9c1d8
budget_msg_ = 'Tool-call budget exceeded; no more tools will run this turn.'
cancel_msg_ = 'Not run: the user stopped this turn.'
cancelled_reply_ = '(stopped by the user)'

def _chunk_text(o):
    "The plain text of one streamed chunk dict. Raw and markdown mode see the same chunks."
    return ''.join(c.get('text', '') for c in (o.get('content') or [])
                   if isinstance(c, dict) and c.get('type') == 'text') if isinstance(o, dict) else ''

def _chunk_thought(o):
    "The thinking of one streamed chunk dict."
    return (o.get('channels') or {}).get('thought', '') if isinstance(o, dict) else ''
dflt_final_prompt_ = ("You've reached the tool-call budget for this turn. Stop calling tools and "
                      "answer with what you already have.")

class ContextWindowExceededError(RuntimeError):
    "Raised when a turn can't finish because the context window filled up and truncate-and-retry recovery also failed."

# backends surface an overflow as a plain RuntimeError/ValueError whose text is all we have to go on
_ctx_err_markers = ('context window', 'context length', 'max number of tokens', 'out of bounds',
                    'kv cache', 'n_ctx', 'exceed context', 'available state entries')

def is_ctx_error(chat, e):
    "Best-effort: does `e`, raised from a backend step, look like the context window filling up?"
    if any(m in str(e).lower() for m in _ctx_err_markers): return True
    try: return bool(chat.ctx_limit) and chat.pct_full >= 1
    except Exception: return False


# %% ../nbs/00_core.ipynb #7757316ddbeb90fa
class Chat:
    "Backend-agnostic chat: `Chat(model)` dispatches to the litert/llama/mlx subclass by `runtime`/model shape."
    _dflt_cbs = []
    _stream_raw = False      # `stream='raw'` yields chunk dicts instead of markdown strings
    _media_ok = True         # can this transport carry pictures and sound? Text-only ones set False
    _media_note = ''         # ...and say there what to use instead

    def _check_media(self):
        "Refuse media a text-only transport cannot carry, rather than dropping it in silence."
        if self._media_ok: return
        c = (self.turn_msg or {}).get('content')
        if isinstance(c, list) and any(is_media(p) for p in c): raise TypeError(self._media_note)

    def _emit(self, o, fmt):
        "One streamed chunk: the raw dict in raw mode, else `fmt`-rendered markdown (falsy = emit nothing)."
        return o if self._stream_raw else fmt.format_item(o)
    def __new__(cls, model=None, *, runtime=None, model_path=None, **kw):
        if cls is not Chat: return super().__new__(cls)
        nm, _ = resolve_runtime(model, runtime, model_path)
        sub = get_runtime(nm)
        # go through the subclass's own `__new__` rather than `object.__new__` directly, so a backend
        # can re-route further (MlxChat picks MlxVlmChat for a vision repo)
        return sub.__new__(sub, model, runtime=runtime, model_path=model_path, **kw)

    def fmt2hist(self, msgs):
        "Backend messages -> canonical rishi history dicts. Backends override this, and the base just normalizes."
        return self.mk_msgs(msgs)

    def _setup(self, model=None, sp='', messages=None, tools=None, approve=None, tool_max_len=None,
               max_steps=10, parallel_tools=False, max_parallel_tools=None, final_prompt=dflt_final_prompt_, cbs=None, default_cbs=True):
        "Shared init tail: strip runtime prefix, store shared fields, build canonical history, register callbacks."
        _, model = split_runtime(model)
        if max_parallel_tools is not None and max_parallel_tools < 1:
            raise ValueError('max_parallel_tools must be at least 1')
        self.tools = L(tools)
        self.hist = self.fmt2hist(messages)
        store_attr('sp,approve,tool_max_len,max_steps,parallel_tools,max_parallel_tools,final_prompt', self)
        self.use, self.cbs, self.turn_msg, self.turn_res = UsageStats(), L(), None, None
        self._steps, self._budget_exceeded, self._final_sent = 0, False, False
        self._cancel = threading.Event()
        if default_cbs: self.add_cbs(self._dflt_cbs)
        self.add_cbs(cbs)
        return model

    @property
    def runtime(self): return self._runtime
    @property
    def pct_full(self): return self.token_count / self.ctx_limit

    def add_cb(self, cb):
        'Register a callback, class or instance. Binds `cb.chat` and returns the instance.'
        if isinstance(cb, type): cb = cb()
        cb.chat = self; self.cbs.append(cb); return cb
    def add_cbs(self, cbs):
        'Register several callbacks and return the `L` of registered instances.'
        return L(cbs).map(self.add_cb)
    def remove_cb(self, cb):
        'Remove a callback by instance, or by class to drop every callback of that type.'
        keep = (lambda c: not isinstance(c, cb)) if isinstance(cb, type) else (lambda c: c is not cb)
        self.cbs = self.cbs.filter(keep); return self
    def remove_cbs(self, cbs):
        'Remove multiple callbacks (by instance or class).'
        L(cbs).map(self.remove_cb); return self

    def __call__(self, msg=None, stream=False, max_output_tokens=None, cbs=None):
        '''Run one chat turn; a `Resp`, or a generator when `stream` is set.
        `stream=True` yields markdown strings, ready to print or hand to `display_stream`.
        `stream='raw'` yields the underlying chunk dicts instead, for programmatic consumers that
        want the text/thinking/tool-call structure rather than rendered markdown.
        One `Chat` is one conversation: `hist`, the turn state and the backend cache are all shared
        mutable state, so a single instance is not safe to drive from two threads at once.'''
        self.use, self._steps, self._budget_exceeded, self._final_sent = UsageStats(), 0, False, False
        self._cancel.clear()
        self._stream_raw = stream == 'raw'
        if stream: return self._stream_turn(msg, max_output_tokens, cbs)
        added = self.add_cbs(cbs)
        try:
            r = self._send(msg, max_output_tokens)
            if self._budget_exceeded and not self._final_sent:
                self._final_sent = True
                r = self._send(self.final_prompt, max_output_tokens)
            return r
        finally: self.remove_cbs(added)

    def _stream_turn(self, msg, max_output_tokens=None, cbs=None):
        'Stream one turn, plus a `final_prompt` round if the tool-call budget ended it early.'
        r = yield from self._stream(msg, max_output_tokens, cbs)
        if self._budget_exceeded and not self._final_sent:
            self._final_sent = True
            r = yield from self._stream(self.final_prompt, max_output_tokens, cbs)
        return r

    def _recreate_conv(self):
        "Rebuild whatever conversation state the backend holds from `self.hist`. A no-op for backends that re-send the whole message list every call, such as llama and remote. mlx drops its KV cache, and litert recreates its `Conversation`."
        pass

    def _set_sp(self, sp):
        "Note a new system prompt wherever the backend keeps one of its own. `_recreate_conv` applies it."
        pass

    def _set_tools(self, tools):
        "Rebuild whatever tool state the backend holds: wire schemas, a call namespace."
        pass

    def reconfigure(self, sp=None, tools=None):
        "Change `sp` or `tools` on a live conversation, keeping `hist`. `None` leaves that half alone, and `tools=()` removes every tool."
        if sp is not None: self.sp = sp; self._set_sp(sp)
        if tools is not None: self.tools = L(tools); self._set_tools(self.tools)
        self._recreate_conv()
        return self

    def oneshot(self, prompt, sp='', think=None, max_tokens=None):
        "One stateless reply: no history, no tools, nothing kept. `think=False` asks the model not to deliberate."
        return self._oneshot(prompt, sp, think=think, max_tokens=max_tokens)

    def _oneshot(self, prompt, sp='', think=None, max_tokens=None):
        "One stateless completion's text. Every backend implements it, and `oneshot` is the public door."
        raise NotImplementedError

    def recover_context(self, error, max_output_tokens=None):
        "Backend contract for recovering from a full context window. Backends override this."
        raise ContextWindowExceededError(f'context recovery is not implemented for {type(self).__name__}') from error

    def cancel(self):
        """Ask the turn in flight to stop at its next safe point. Safe to call from another thread.

        Cooperative, not a kill: the loop stops between chunks and between tool calls, so `hist` is
        left with a `tool` result for every `tool_call` and the next turn can be sent. What it costs
        is that a backend with no abort seam finishes the completion it is already inside.
        """
        self._cancel.set()
        return True

    @property
    def cancelled(self): return self._cancel.is_set()

    def close(self):
        "Release backend resources (overridden per backend)."
        pass
    def __del__(self):
        try: self.close()
        except Exception: pass

    def print_hist(self):
        "Render the conversation history as markdown (plain text outside a notebook)."
        md = '\n\n---\n\n'.join(f"**{m.get('role','?')}**\n\n{Resp(m)._repr_markdown_()}" for m in self.hist)
        try: from IPython.display import Markdown, display; display(Markdown(md))
        except Exception: print(md)

