_pyfence_re = re.compile(r'^```(?:python|py)[ \t]*\n(.*?)\n```', re.DOTALL | re.MULTILINE)

def extract_code(text):
    'Code of the last ```python fence in `text`, else None.'
    return ms[-1] if (ms := _pyfence_re.findall(text or '')) else None

def extract_fence(text, tag='answer'):
    'Contents of the last ```<tag> fence in `text`, else the whole stripped text.'
    ms = re.findall(rf'^```{tag}[ \t]*\n(.*?)\n```', text or '', re.DOTALL | re.MULTILINE)
    return ms[-1] if ms else (text or '').strip()

def matches_(actual, expected):
    'True if `actual` contains any value in `expected` (a scalar, or a list of accepted values).'
    return any(str(e) in (actual or '') for e in listify(expected))

def mk_result_fence(out):
    'Feed a code result back, prompting a prose answer or more code.'
    return (f"```result\n{out}\n```\n\nIf this answers the request, reply with the final answer in prose; "
            "only write another ```python block if you need to run more code.")

def run_coro(coro):
    'Run an awaitable to completion from sync code, even inside a running event loop.'
    try: asyncio.get_running_loop()
    except RuntimeError: return asyncio.run(coro)
    with ThreadPoolExecutor(1) as ex: return ex.submit(asyncio.run, coro).result()

@contextmanager
def killed_on_exit(proc, timeout=2):
    """Run a block over `proc`; leaving it early kills the child rather than waiting for it.

    `with Popen(...)` calls `wait()` with no timeout, so a generator abandoned mid-stream blocks its
    caller until the CLI finishes work nobody wants any more. A block that ends normally still
    waits, and leaves the pipes open for the caller to read `stderr` from.
    """
    try: yield proc
    except BaseException:
        if proc.poll() is None:
            proc.terminate()
            try: proc.wait(timeout)
            except subprocess.TimeoutExpired: proc.kill(); proc.wait()
        for p in (proc.stdin, proc.stdout, proc.stderr):
            if p is not None:
                try: p.close()
                except Exception: pass
        raise
    else: proc.wait()

def sync_iter(agen_fn, stop=None):
    '''Drive the async generator returned by `agen_fn()` from sync code, yielding its items.

    The whole generator runs on one event loop in one background thread, rather than a fresh loop per
    item: a streaming HTTP response is bound to the loop that opened it, so pumping it with repeated
    `asyncio.run` calls would tear the connection down mid-stream.

    `stop` is an event polled after each item. Setting it closes the async generator on the loop that
    opened it, which is what ends a provider's HTTP stream. Without it, abandoning this generator
    only stops the *consumer*: the pump thread is detached and its queue is unbounded, so the model
    goes on generating, and billing, until the response ends by itself.'''
    from queue import Queue
    from threading import Thread
    q, done = Queue(), object()
    async def _pump():
        agen = agen_fn()
        try:
            async for o in agen:
                q.put(o)
                if stop is not None and stop.is_set(): break
        except BaseException as e: q.put(e)
        finally:
            try: await agen.aclose()
            except BaseException: pass
            q.put(done)
    t = Thread(target=lambda: asyncio.run(_pump()), daemon=True)
    t.start()
    try:
        while (o := q.get()) is not done:
            if isinstance(o, BaseException): raise o
            yield o
    finally: t.join(timeout=5)

@patch
def run_py(self:Chat, code, ban_defs=False, g=None):
    'Run `code` in this chat\'s sandboxed, persistent namespace, and return stdout plus the last expression\'s repr.'
    if not hasattr(self, '_pyrun'): self._pyrun = RunPython(g=g, ban_defs=ban_defs)
    buf = io.StringIO()
    try:
        with redirect_stdout(buf): res = run_coro(self._pyrun(code))
        out = buf.getvalue()
        if res is not None: out = (out + '\n' if out else '') + repr(res)
        return out or '(ok)'
    except Exception as e: return f"{type(e).__name__}: {e}"

def task_complete(chat):
    "`done` policy: judge (via `classify`, isolated) whether the latest result completes the request."
    convo = '\n'.join(f"{m.get('role','?')}: {resp_text(m)}" for m in chat.hist[-6:])
    return chat.classify(convo, ['complete', 'needs_more_work']) == 'complete'

def output_matches(expected):
    "`done` policy: stop once the last code output contains `str(expected)` (e.g. the answer to match against)."
    return lambda chat: matches_(getattr(chat, 'turn_code_out', ''), expected)

class PyFenceCallback(ChatCallback):
    "Run ```python fences, feed results back, loop until `done(chat)` (default: no fence). `max_rounds` is a safety cap."
    order = 50
    def __init__(self, max_rounds=5, done=None, pyrun:callable=None):
        store_attr(); self._depth = 0; self._warned = False
    def _active(self):
        "Only the last-registered `PyFenceCallback` drives a turn. Earlier ones yield, so a per-call `done` is not defeated by a persistent one."
        cbs = getattr(self.chat, 'cbs', L())
        later = self in cbs and any(isinstance(cb, PyFenceCallback) for cb in cbs[cbs.index(self)+1:])
        if later and not self._warned:
            warnings.warn('This chat already has a PyFenceCallback; the last-registered one drives the turn.')
            self._warned = True
        return not later
    def _run_code(self):
        "Run the last python fence. Returns `(output, done)`, or `(None, False)` at the cap or with no fence."
        if self._depth >= self.max_rounds: return None, False
        code = extract_code(resp_text(self.chat.turn_res))
        if not code: return None, False
        tc = {'function': {'name': 'python', 'arguments': {'code': code}}}
        fn = self.pyrun or self.chat.run_py
        out = 'Denied by human' if (self.chat.approve and not self.chat.approve(tc)) else fn(code)
        self.chat.turn_code_out = out
        return out, bool(self.done and self.done(self.chat))
    def after_response(self):
        "Feed the fence result back. Re-queries synchronously, or returns a chunk generator during a streamed turn."
        if not self._active(): return
        if getattr(self.chat, '_streaming', False): return self._after_stream()
        out, done = self._run_code()
        if out is None: return
        self._depth += 1
        try:
            if done: self.chat.hist.append(self.chat.fmt2hist([out])[0])   # record clean output; no extra model call
            else: self.chat._send(mk_result_fence(out))                   # feed result back for another round
        finally: self._depth -= 1
    def _after_stream(self):
        "Streaming feedback: emit the result into the stream, then (unless done) stream the follow-up reply."
        out, done = self._run_code()
        if out is None: return
        self._depth += 1
        try:
            if done: self.chat.hist.append(self.chat.fmt2hist([out])[0]); yield f"\n\n```result\n{out}\n```\n"; return
            rf = mk_result_fence(out)
            yield '\n\n' + rf + '\n\n'
            yield from self.chat._stream(rf)
        finally: self._depth -= 1

